pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed newOwner; the admin is the deployer (this test contract), which is the msg.sender used in setUp() creating c
    function testFuzz_property(address newOwner) public {
        // avoid zero-address weirdness but keep wide domain
        vm.assume(newOwner != address(0));

        // The deployer (this contract) is admin because c was created in setUp() by this contract
        // call setOwner as admin
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // The reference contract: whenever an admin calls setOwner(newOwner) it returns true and sets owner to newOwner.
        // We assert the general property by reading the public getter owner().
        // This will hold for all inputs on the reference, but on the mutant (which doesn't assign) it will fail for some newOwner.
        assertTrue(ok && c.owner() == newOwner);
    }
}

