pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public { c = new C(); admin = address(this); }

    // The fuzzed parameter is the candidate newOwner address supplied to setOwner.
    function testFuzz_property(address newOwner) public {
        // keep wide domain but avoid the zero address if desired; we do not exclude it wholly
        // because the property must hold for ALL inputs: reference sets owner == newOwner.
        // Ensure the call is made as the admin (constructor set admin to msg.sender, which is this test contract)
        vm.prank(admin);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract: after a successful call, owner() == newOwner.
        // We assert the universal property: if call succeeded, the owner equals the supplied newOwner.
        // This will hold for the reference for all inputs; the mutant that assigns address(0) will fail
        // for any newOwner != address(0) (and so the fuzzer can find such an input).
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted (shouldn't in reference), still assert that owner didn't change to address(0)
            // but to keep a single assertion as required, we assert owner equals newOwner only when call succeeded.
            // For the purposes of this test the reference does not revert here; the mutant also doesn't revert.
            assertTrue(c.owner() == newOwner);
        }
    }
}

