pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address that will attempt to call setOwner and the newOwner address to set
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses non-zero to be meaningful, but otherwise wide
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // admin is the deployer set in setUp(); that's address(this) at deployment time in setUp()
        address admin = address(this);

        // ensure we consider the scenario where caller is owner but not admin and when caller is not owner
        // First, read initial owner (should be the deployer of C in setUp())
        address initialOwner = c.owner();

        // The general property: only admin can call setOwner. So if caller != admin, call should revert / fail.
        // We execute the call as the fuzzed caller and catch whether it succeeded.
        bool ok;
        try c.setOwner(newOwner) {
            // if executed directly here, it's from this test contract (admin) — but we need to simulate call from caller
            // So instead we use vm.prank to impersonate caller and call setOwner, catching revert via low-level try/catch
            // Reset ok since this path is not used
            ok = true;
        } catch {
            ok = false;
        }

        // Now perform the real attempted call as the fuzzed caller via vm.prank and capture success via try/catch
        bool callSucceeded;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }

        // After the attempt, read the owner
        address finalOwner = c.owner();

        // The invariant to assert: if caller is not the admin (deployer), then setOwner must NOT succeed and owner must remain unchanged.
        // This holds for the reference contract for all inputs, but the mutant (which permits owner to act as admin) will allow the call when
        // caller == initialOwner and initialOwner != admin, changing owner — thus breaking this assertion for some inputs.
        if (caller != admin) {
            // require that the call did not succeed and owner unchanged
            assertTrue(!callSucceeded && finalOwner == initialOwner);
        } else {
            // when caller == admin, the call is allowed; owner should have been updated
            assertTrue(callSucceeded && finalOwner == newOwner);
        }
    }
}

