pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller is the address that will attempt to call setOwner;
    // newOwner is the address passed into setOwner.
    function testFuzz_property(address caller, address newOwner) public {
        // Keep inputs broad but avoid the trivial case where caller is the deployer (admin)
        // because the reference allows the deployer to call setOwner legitimately.
        // We want to assert that when caller != deployer, calling setOwner as caller
        // does NOT change owner under the reference implementation.
        address deployer = address(this);

        vm.assume(caller != deployer);

        // Record owner before the attempted call
        address ownerBefore = c.owner();

        // Have the fuzzed caller attempt to call setOwner(newOwner)
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }

        // After the attempted call, read owner
        address ownerAfter = c.owner();

        // GENERAL RULE (one assert): For any caller != deployer, the reference C will NOT allow that caller
        // to change owner; therefore ownerAfter must equal ownerBefore for all admissible inputs.
        // The mutant (which checks owner instead of admin in onlyAdmin) will allow the current owner
        // (when owner != deployer) to call setOwner and change owner, causing this assertion to fail
        // for some fuzzed inputs. We perform no other assertions.
        assertTrue(ownerAfter == ownerBefore);
    }
}

