pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller tries to call setOwner with newOwner
    // We must allow the fuzzer to pick addresses; keep admissible domain wide
    function testFuzz_property(address caller, address newOwner) public {
        // Avoid trivial zero-address newOwner to keep domain wide but sensible
        // (still allow zero if fuzzer picks it)
        // Ensure caller is not the deployer (admin) in many cases so we can detect mutant
        address admin = address(this); // setUp deployer

        // Make caller have some ETH so that vm.prank can act as them (not strictly necessary but harmless)
        vm.deal(caller, 1 ether);

        // Record owner before the attempted call
        address ownerBefore = c.owner();

        // The reference requires only admin can call setOwner; so if caller != admin,
        // then the call should not change owner. We will attempt the call and ignore revert (capture success).
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // After the call attempt, read owner
        address ownerAfter = c.owner();

        // General invariant (single assert): In the correct contract, any caller who is NOT the deployer
        // cannot change owner: ownerAfter == ownerBefore whenever caller != admin.
        // This is a universal property the reference satisfies for all inputs; the mutant (which lets owner call)
        // will violate it for inputs where caller equals current owner and owner != admin.
        if (caller != admin) {
            assertTrue(ownerAfter == ownerBefore);
        } else {
            // If caller == admin, reference allows change — then after successful call owner should be newOwner
            // (we still must use a single assert across all branches; we implement it by composing a boolean)
            // Consolidate into single boolean for assertTrue below
            assertTrue(ownerAfter == (ok ? newOwner : ownerBefore));
        }
    }
}

