pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: caller (the address who will attempt to call setOwner)
    // and newOwner (the address to set as owner)
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide but avoid zero-address for clearer semantics
        // Allow caller and newOwner to be any addresses including equal to deployer
        // We will construct a scenario where caller == current owner but caller != admin.

        // admin is the deployer (address(this) at construction?), actually c was deployed by this test contract in setUp(), so admin == address(this)
        address admin = address(this);

        // Ensure fuzz can pick an address that can become owner but is not admin.
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Step 1: As admin (this test contract) set owner to caller — this is allowed by the correct contract.
        // Now current owner becomes 'caller'. In the correct contract only admin can call setOwner; here admin==address(this)
        bool ok;
        try c.setOwner(caller) { ok = true; } catch { ok = false; }
        // sanity: the correct contract should let admin set owner
        assertTrue(ok);
        assertTrue(c.owner() == caller);

        // Now we test that only admin (not the current owner when different from admin) can change owner.
        // We restrict to the interesting case: caller (current owner) is NOT the admin.
        vm.assume(caller != admin);

        // Now the current owner (caller) will attempt to call setOwner(newOwner).
        vm.prank(caller);
        bool ok2;
        try c.setOwner(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // GENERAL RULE (single assertion): In the reference contract, since only admin can call setOwner,
        // a call made by the current owner when that owner is not the admin must NOT succeed in changing owner.
        // We therefore assert that after the attempted call by the current owner (who is not admin),
        // either the call reverted (ok2 == false) OR the owner remained unchanged (c.owner() == caller).
        // This single assertTrue captures that property for all admissible inputs; the mutant (which allows owner to act as admin)
        // will for some fuzzed inputs make ok2 == true and c.owner() == newOwner, violating this assertion.
        assertTrue(!ok2 || c.owner() == caller);
    }
}

