    function testFuzz_property(address newOwner) public {
        // keep domain wide: disallow zero address only if desired, but the original contract allows any address,
        // so we do not restrict newOwner. The property: call completes and returns true on reference for all inputs.

        // Call setOwner as the admin (the contract was deployed in setUp by this test contract)
        bool ok;
        // perform the external call and capture whether it reverted or not
        try c.setOwner(newOwner) returns (bool ret) {
            // call completed; ensure returned value is true (reference guarantees this)
            ok = ret;
        } catch {
            // if it reverted, mark ok = false; reference should not revert here when called by admin
            ok = false;
        }

        // The single assertion: for every fuzzed newOwner, the reference contract returns true (ok == true).
        // The mutant that returns false after setting owner will cause this assert to fail for those inputs,
        // so the test passes on reference and fails on the mutant for some fuzzed addresses.
        assertTrue(ok);
    }
}

