import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the newOwner and an address that will act as admin (the deployer is admin by constructor)
    function testFuzz_property(address potentialNewOwner) public {
        // Keep the fuzzed address wide but non-zero to be meaningful as an owner
        vm.assume(potentialNewOwner != address(0));

        // The reference contract C sets owner in constructor to the deployer (this test contract)
        // We call setOwner as that deployer (admin) using vm.prank to be msg.sender == admin
        // Use address(this) because setUp deployed C from this same contract
        bool ok;
        vm.prank(address(this));
        try c.setOwner(potentialNewOwner) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // GENERAL RULE: In the correct contract, any successful call to setOwner by admin returns true.
        // We assert that the call we just made returned true (ok == true). The mutant that flips/zeros admin
        // inside onlyAdmin can alter subsequent observable behavior; the fuzzer will find inputs where
        // behavior diverges across versions because the reference always returns true here for any input.
        assertTrue(ok);
    }
}
